import hashlib

N_PARTITIONS = 1024  # fixed forever, far more than nodes; never hash % node_count

# partition -> node map lives in metadata (etcd, a config table), not in code
partition_map = {p: f"db-{p % 4}" for p in range(N_PARTITIONS)}

def partition_of(key: str) -> int:
    # Stable hash: Python's built-in hash() is randomized per process
    digest = hashlib.md5(key.encode()).digest()
    return int.from_bytes(digest[:8], "big") % N_PARTITIONS

def node_for(tenant_id: str) -> str:
    return partition_map[partition_of(tenant_id)]

def hot_write_key(tenant_id: str, seq: int, salts: int = 8) -> str:
    # A whale tenant's writes spread over 8 partitions; its reads fan out to 8, not 1024
    return f"{tenant_id}#{seq % salts}"

def add_node(new_node: str, share: float) -> int:
    # Rebalance by moving whole partitions; no key is ever rehashed
    moved = list(range(0, N_PARTITIONS, round(1 / share)))
    for p in moved:
        partition_map[p] = new_node  # copy the partition's data first, then flip the map
    return len(moved)

print(add_node("db-4", share=0.2))  # 205 of 1024 partitions move (~20%)
